def finish(sections, lang, tree_aria, tree_cap):
    """Insert the drills and the dependency tree (shared, language-specific data) into the sections."""
    for sec in sections:
        bl = sec["blocks"]
        for i, b in enumerate(bl):
            if b == ("html", "TREE"):
                bl[i] = ("html", tree(lang, tree_aria, tree_cap))
        if sec["id"] == "practice" and not any(b[0] == "drill" for b in bl):
            bl.extend(chain_drills.drill_blocks(lang))
    return sections


