SECTIONS = {"ru": RU, "en": EN, "uz": UZ}


def check_numbers():
    import math
    import sympy as sp
    chain_drills.verify()
    x, y, t, h, w, b = sp.symbols("x y t h w b", real=True)
    ok = lambda e: sp.simplify(e) == 0
    # the definition section
    assert ok(sp.limit(((x + h) ** 2 - x ** 2) / h, h, 0) - 2 * x)
    assert ok(sp.limit((sp.sin(x + h) - sp.sin(x)) / h, h, 0) - sp.cos(x))
    # two ways
    assert ok(sp.limit(((3 * x + 3 * h + 1) ** 2 - (3 * x + 1) ** 2) / h, h, 0) - (18 * x + 6))
    assert ok(sp.limit((sp.sqrt((x + h) ** 2 + 1) - sp.sqrt(x ** 2 + 1)) / h, h, 0) - x / sp.sqrt(x ** 2 + 1))
    f = lambda v: math.exp(v * v)
    rows = [(0.1, 3.35348, 6.35203, 0.91546), (0.01, 2.77347, 5.51903, 0.08246), (0.001, 2.72373, 5.44473, 0.00816), (0.0001, 2.71883, 5.43738, 0.00082)]
    for hh, fv, q, gap in rows:
        qq = (f(1 + hh) - f(1)) / hh
        assert round(f(1 + hh), 5) == fv and round(qq, 5) == q and round(qq - 2 * math.e, 5) == gap, (hh, f(1 + hh), qq, qq - 2 * math.e)
    assert round(3 * math.e, 2) == 8.15
    # long chain at a point
    yy = sp.log(1 + (2 * x + 1) ** 2)
    assert sp.diff(yy, x).subs(x, 0) == 2
    assert ok(sp.diff(sp.sin(3 * x) ** 2, x) - 3 * sp.sin(6 * x))
    assert ok(sp.diff(x ** 2 * sp.exp(3 * x), x) - x * sp.exp(3 * x) * (3 * x + 2))
    # partials by definition
    F = x ** 2 * y + sp.sin(y)
    assert ok(sp.diff(F, x) - 2 * x * y) and ok(sp.diff(F, y) - (x ** 2 + sp.cos(y)))
    # the non-differentiable counterexample
    g = x ** 2 * y / (x ** 2 + y ** 2)
    assert sp.limit(g.subs({x: h, y: 0}) / h, h, 0) == 0 and sp.limit(g.subs({x: 0, y: h}) / h, h, 0) == 0
    assert ok(g.subs({x: t, y: t}) - t / 2)
    # total derivative, implicit
    assert ok(sp.diff(x * x ** 2, x) - 3 * x ** 2)
    # the neuron
    sig = lambda v: 1 / (1 + math.exp(-v))
    z = 0.5 * 2 - 1; a = sig(z); L = 0.5 * (a - 1) ** 2
    assert z == 0 and a == 0.5 and L == 0.125
    d = (a - 1) * a * (1 - a)
    assert d == -0.125 and d * 2 == -0.25
    w2, b2 = 0.5 - d * 2, -1 - d
    z2 = w2 * 2 + b2; a2 = sig(z2); L2 = 0.5 * (a2 - 1) ** 2
    assert (w2, b2, z2) == (0.75, -0.875, 0.625) and round(a2, 4) == 0.6514 and round(L2, 4) == 0.0608, (a2, L2)
    # worked examples
    assert ok(sp.diff((2 * x + 3) ** 2, x) - (8 * x + 12))
    assert round(2 * math.cos(1), 4) == 1.0806 and round(math.sin(2), 4) == 0.9093
    assert round(math.sin(4), 3) == -0.757 and round(math.sin(2) ** 2, 3) == 0.827
    for hh, q in ((0.1, 1.04987), (0.01, 1.00500), (0.001, 1.00050)):
        assert round((math.exp(math.sin(hh)) - 1) / hh, 5) == q, (hh, (math.exp(math.sin(hh)) - 1) / hh)
    assert ok(sp.diff(sp.log(sp.cos(3 * x)), x) + 3 * sp.tan(3 * x))
    A = x + y ** 2
    assert ok(sp.diff(A ** 3, x) - 3 * A ** 2) and ok(sp.diff(A ** 3, y) - 6 * y * A ** 2)
    assert ok(sp.limit(((x + h + y ** 2) ** 3 - A ** 3) / h, h, 0) - 3 * A ** 2)
    assert ok(sp.limit(((x + (y + h) ** 2) ** 3 - A ** 3) / h, h, 0) - 6 * y * A ** 2)
    assert ok(sp.diff((x + y) * (x - y), x) - 2 * x) and ok(sp.diff((x + y) * (x - y), y) + 2 * y)
    a_, y_ = sp.symbols("a y_", positive=True)
    Lce = -(y_ * sp.log(a_) + (1 - y_) * sp.log(1 - a_))
    assert ok(sp.diff(Lce, a_) * a_ * (1 - a_) - (a_ - y_))
    return True


if __name__ == "__main__":
    print("numbers ok" if check_numbers() else "")
